"""论文第五节 B 中用于对照的三个算法。

论文原文给出的三个对照方案：

  1) JBHCO-PB（Polling + BCD）
     "polling strategy is used for periodic BHTP design, in which each satellite
      illuminates the cells yielding the maximum capacity. The offloading problem
      is solved via BCD algorithm."
     → 轮询 BHTP + 与本文相同的 Algorithm 3（BCD）卸载求解。
        与 JBHCO-MB 的唯一差别：BHTP 不是匹配得到的，也不做 swap 改进。

  2) CL（Computing Locally）
     "each computing task generated by ground user is processed locally."
     → 所有任务本地计算，λ_i = T^l_i / D_i = O_i /(D_i f^l_i)。

  3) JBHCO-PG（Polling + Greedy）
     "the greedy strategy is adopted for computing offloading, meaning tasks are
      always offloaded to satellites with considerable ability for processing.
      The polling strategy derived from [17] is used for BHTP design."
     → 轮询 BHTP + 贪婪卸载：所有用户都卸载，各自挑"能给它最快完成"的照明卫星；
        卫星按各用户工作量 O_i 成比例预留算力（论文式 (15) 下方说明卫星在确定
        服务用户后即为待处理任务预留计算资源）。没有本地/卸载的二选一决策，
        因此当卫星算力紧张时表现最差，这与论文图 3~图 9 中 JBHCO-PG 始终最差一致。
"""

from __future__ import annotations

import math
from typing import Dict, List

from channel_model import ChannelModel
from config import SimConfig
from satellite_network import SatelliteNetwork
from solvers import (
    FeasibleSolutionNotFoundError,
    AccessMatrix,
    ResourceMatrix,
    communication_overhead_s,
    design_polling_beam_hopping,
    illuminating_satellites,
    local_latency_s,
    solve_joint_offloading_and_allocation,
    validate_solution,
)


# =====================================================================
# 1. CL：全部本地计算
# =====================================================================
def run_computing_locally(
    config: SimConfig,
    network: SatelliteNetwork,
    channel_model: ChannelModel,
) -> Dict[str, object]:
    """对照算法 CL：所有任务都在本地处理。

    λ_i = T^l_i / D_i = O_i / (D_i f^l_i)（论文式 (10)(19)）。
    这条曲线与带宽、卫星数、卫星算力都无关，只随 f^l_i、O_i、M_i 变化 ——
    论文图 4、图 7、图 8、图 9 中 CL 是一条水平线，正是这个原因。
    """
    normalized = [local_latency_s(task) / task.max_latency_s for task in network.user_tasks]
    latencies = [local_latency_s(task) for task in network.user_tasks]
    if any(not math.isfinite(v) or v > 1.0 + 1e-7 for v in normalized):
        # CL 没有可调变量；本地方案超时只能报告该基线不可行。
        raise FeasibleSolutionNotFoundError("CL 本地方案违反 C4；不代表联合卸载问题无解")
    return {
        "algorithm": "CL",
        "max_lambda": max(normalized, default=0.0),
        "objective_value": max(normalized, default=0.0),
        "maximum_latency_s": max(latencies, default=0.0),
        "latencies_s": latencies,
        "normalized_latencies": normalized,
        "local_users": [task.user_id for task in network.user_tasks],
        "offloaded_users": [],
        "constraint_C4_ok": True,  # 上方已按统一残差量级检查 C4。
    }


# =====================================================================
# 2. JBHCO-PB：轮询 BHTP + BCD 卸载
# =====================================================================
def run_jbhco_pb(
    config: SimConfig,
    network: SatelliteNetwork,
    channel_model: ChannelModel,
) -> Dict[str, object]:
    """对照算法 JBHCO-PB：轮询 BHTP + Algorithm 3（BCD）。

    与 JBHCO-MB 的差别只有 BHTP 的来源：
      JBHCO-MB：匹配理论初始解 + N_max 次 swap 改进（响应业务分布和干扰）
      JBHCO-PB：固定节拍轮询，不做任何改进
    所以两者的差距就是论文强调的"swap 能找到更好的 BHTP、带来更多容量"。
    """
    plan = design_polling_beam_hopping(config, network, channel_model)
    result = solve_joint_offloading_and_allocation(config, network, channel_model, plan)
    latency_result = result["latency_result"]
    return {
        "algorithm": "JBHCO-PB",
        "beam_hopping_plan": plan,
        "access_matrix": result["access_matrix"],
        "allocation": result["allocation"],
        "max_lambda": float(result["max_lambda"]),
        "objective_value": float(result["max_lambda"]),
        "maximum_latency_s": latency_result["maximum_latency_s"],
        "latencies_s": latency_result["latencies_s"],
        "normalized_latencies": latency_result["normalized_latencies"],
        "local_users": latency_result["local_users"],
        "offloaded_users": latency_result["offloaded_users"],
        "constraint_C4_ok": latency_result["constraint_C4_ok"],
        "bcd_history": result["bcd_history"],
    }


# =====================================================================
# 3. JBHCO-PG：轮询 BHTP + 贪婪卸载
# =====================================================================
def run_jbhco_pg(
    config: SimConfig,
    network: SatelliteNetwork,
    channel_model: ChannelModel,
) -> Dict[str, object]:
    """对照算法 JBHCO-PG：轮询 BHTP + 贪婪卸载（所有任务都上星）。

    贪婪规则分两步：
      步骤 1（选星）：每个用户在所有照明过它的卫星里，挑通信开销
                      M_i/C^BH + 2d/c + T_BH 最小的那颗，即"最快能把数据送上去"。
                      这一步不看卫星上已经排了多少任务 —— 这正是贪婪策略的短板。
      步骤 2（分算力）：每颗卫星把 f_max 按它所服务用户的工作量 O_i 成比例预留。
                      对同一颗星上的用户来说，这等价于让它们的处理时延相等。

    因为没有"本地 vs 卸载"的选择，一旦某颗卫星被塞进过多用户，
    最大 λ_i 会迅速恶化，对应论文图 5 中 JBHCO-PG 在 O_i=350 时高达 0.928。
    """
    plan = design_polling_beam_hopping(config, network, channel_model)
    capacity_table = channel_model.average_capacity_table(plan)
    num_satellites = len(network.satellites)
    num_users = len(network.user_tasks)

    access_matrix: AccessMatrix = [[0] * num_users for _ in range(num_satellites)]
    allocation: ResourceMatrix = [[0.0] * num_users for _ in range(num_satellites)]

    # ---- 步骤 1：贪婪选择接入卫星 ----
    for user_index, task in enumerate(network.user_tasks):
        candidates = illuminating_satellites(plan, task.cell_id)
        best_sat, best_overhead = None, float("inf")
        for sat_id in candidates:
            overhead = communication_overhead_s(config, network, task, sat_id, capacity_table)
            if overhead < best_overhead:
                best_sat, best_overhead = sat_id, overhead
        if best_sat is not None:
            access_matrix[best_sat][user_index] = 1

    # ---- 步骤 2：每颗卫星按工作量比例预留算力 ----
    for sat_id in range(num_satellites):
        served = [i for i in range(num_users) if access_matrix[sat_id][i] == 1]
        if not served:
            continue
        total_cycles = sum(network.user_tasks[i].required_cycles for i in served)  # Σ O_i
        for i in served:
            share = network.user_tasks[i].required_cycles / max(total_cycles, 1e-12)
            allocation[sat_id][i] = config.sat_compute_capacity_cps * share

    latency_result = validate_solution(
        config, network, channel_model, access_matrix, allocation, plan
    )
    return {
        "algorithm": "JBHCO-PG",
        "beam_hopping_plan": plan,
        "access_matrix": access_matrix,
        "allocation": allocation,
        "max_lambda": float(latency_result["max_lambda"]),
        "objective_value": float(latency_result["max_lambda"]),
        "maximum_latency_s": latency_result["maximum_latency_s"],
        "latencies_s": latency_result["latencies_s"],
        "normalized_latencies": latency_result["normalized_latencies"],
        "local_users": latency_result["local_users"],
        "offloaded_users": latency_result["offloaded_users"],
        "constraint_C4_ok": latency_result["constraint_C4_ok"],
    }


# =====================================================================
# 4. 统一调度入口
# =====================================================================
BASELINE_RUNNERS = {
    "JBHCO-PB": run_jbhco_pb,
    "CL": run_computing_locally,
    "JBHCO-PG": run_jbhco_pg,
}


def run_baseline(
    name: str,
    config: SimConfig,
    network: SatelliteNetwork,
    channel_model: ChannelModel,
) -> Dict[str, object]:
    """按算法名字调用对应的对照算法。"""
    if name not in BASELINE_RUNNERS:
        raise ValueError(f"未知对照算法 {name}，可选：{list(BASELINE_RUNNERS)}")
    return BASELINE_RUNNERS[name](config, network, channel_model)
